public class Main {
    public static void main(String[] args) throws Exception {
        Cat 甲 = new Cat("{n1}", {c1});
        Cat 乙 = new Cat("{n2}", {c2});

        甲.start();
        乙.start();

        甲.join();
        乙.join();

        System.out.println(甲.名字 + "数到：" + 甲.数到 + " 条");
        System.out.println(乙.名字 + "数到：" + 乙.数到 + " 条");
        System.out.println("一共：" + (甲.数到 + 乙.数到) + " 条");
    }
}

class Cat extends Thread {
    String 名字;
    int 要数;
    int 数到 = 0;

    Cat(String 名字, int 要数) {
        this.名字 = 名字;
        this.要数 = 要数;
    }

    public void run() {
        for (int i = 0; i < 要数; i++) {
            数到 = 数到 + 1;
        }
    }
}
